<div class="modal-cover" hidden="" id="add-modal"><section aria-labelledby="modal-title" aria-modal="true" class="modal-panel" role="dialog"><button aria-label="Close" class="modal-close" onclick="closeAddModal()" type="button">×</button><h2 id="modal-title">Add Business</h2><p>New content will appear in City Up once saved.</p><form id="add-form"><label>Name <input id="entry-name" maxlength="80" name="name" placeholder="Enter name" required=""/></label><label class="entry-category">Category <input maxlength="70" name="category" placeholder="e.g. Restaurant"/></label><label class="entry-location">Location <input maxlength="80" name="location" placeholder="e.g. Tunis"/></label><label class="entry-date" hidden="">Date <input name="date" type="date"/></label><div class="modal-buttons"><button class="cancel-btn" onclick="closeAddModal()" type="button">Cancel</button><button class="save-btn" type="submit">Save</button></div></form></section></div><script src="public/script.js"></script>
